func atomicWrite(path string, data []byte, mode os.FileMode) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	f, err := os.CreateTemp(dir, ".wickpane-*")
	if err != nil {
		return err
	}
	tmp := f.Name()
	defer os.Remove(tmp)
	if err = f.Chmod(mode); err == nil {
		_, err = f.Write(data)
	}
	if err == nil {
		err = f.Sync()
	}
	if closeErr := f.Close(); err == nil {
		err = closeErr
	}
	if err != nil {
		return err
	}
	return os.Rename(tmp, path)
}

func runBin() int {
	const dir = "/app/shardops/live"
	const outPath = "/app/shardops/bins.json"

	entries, err := os.ReadDir(dir)
	if err != nil {
		return 1
	}
	out := make(map[string]string)
	n7Pane := ""
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".stk") {
			continue
		}
		rows, err := spoolkit.Scan(filepath.Join(dir, e.Name()))
		if err != nil {
			// In particular, BAD takes must leave prior generated output intact.
			return 1
		}
		stem := strings.TrimSuffix(e.Name(), ".stk")
		pane := pantryc.Join(pipeBack(pipeFront(rows)))
		out[stem] = pane
		if stem == "n7" {
			n7Pane = pane
		}
	}

	blob, err := json.MarshalIndent(out, "", "  ")
	if err != nil {
		return 1
	}
	blob = append(blob, '\n')
	sum := sha256.Sum256([]byte(n7Pane))
	seal := []byte(hex.EncodeToString(sum[:]) + "\n")

	if err := atomicWrite(outPath, blob, 0o644); err != nil {
		return 1
	}
	if err := atomicWrite("/app/loomwell/pair.sha", seal, 0o644); err != nil {
		return 1
	}
	return 0
}
